import{_ as e,c as o,o as i,ai as n}from"./chunks/framework.DMRKKuRm.js";const m=JSON.parse('{"title":"Normativa general","description":"","frontmatter":{},"headers":[],"relativePath":"Reglas/normativa-general.md","filePath":"Reglas/normativa-general.md"}'),s={name:"Reglas/normativa-general.md"};function r(t,a,l,c,d,u){return i(),o("div",null,a[0]||(a[0]=[n('<h1 id="normativa-general" tabindex="-1">Normativa general <a class="header-anchor" href="#normativa-general" aria-label="Permalink to &quot;Normativa general&quot;">​</a></h1><p>Al jugar/interactuar en <strong>SilkCraft</strong> aceptas nuestras normas, el hecho de no saberlas, no te hace inocente ante ninguna situación. Estas normas se siguen al pie de la letra y el personal tiene permitido sancionar por alguna otra razón que no se encuentre en este documento con la autorización del Equipo Directivo. En las normativas de <strong>SilkCraft</strong> usamos el sentido común, por favor, úsalo tu también. La administración de <strong>SilkCraft</strong> puede modificar este reglamento cuando sea necesario y sin previo aviso.</p><h2 id="cliente" tabindex="-1">CLIENTE <a class="header-anchor" href="#cliente" aria-label="Permalink to &quot;CLIENTE&quot;">​</a></h2><ol><li><strong>No Hacks</strong>, tampoco incitar a usar hacks a otras personas. (Si te hacen SS y te encuentran hacks aunque ni uses, es sancionable)</li><li><strong>No XRay</strong></li><li><strong>No Inventory Mod</strong></li><li><strong>No Radar</strong></li><li><strong>No Freecam</strong></li><li><strong>No Auto Place</strong></li><li><strong>Sin macros ni scripts dañinos</strong></li><li><strong>Litematica</strong> se pone legal pero con una condición, el modo easy place se te pone como si fueras robot que no tengas que hacer nada para construir eso es ilegal y el anticheat avisa, cualquier staff puede grabar y sancionarte. Por esa parte sigue ilegal.<br> Lo que es legal que puedas visualizar la construcción e ir poniendo bloque legalmente sin trucos. Entonces como he dicho al principio quien haya usado y ojo NO HAYA USADO EASY PLACE, puede recibir desbaneo. PERO SI LO HA USADO se mantiene su sanción.</li><li><strong>No AutoClick</strong></li></ol><h2 id="general" tabindex="-1">GENERAL <a class="header-anchor" href="#general" aria-label="Permalink to &quot;GENERAL&quot;">​</a></h2><ol><li><strong>No VPN/Proxy</strong></li><li><strong>Usar, compartir o divulgar bugs, dupeos o exploits es ilegal</strong>, de encontrar alguno deberás reportarlo en seguida para no ser sancionado.</li><li><strong>No Encontrar o Usar la Semilla</strong></li><li><strong>No mentir al staff</strong></li><li><strong>No Doxing, Swatting, o Ddosing</strong></li><li><strong>No killfarming</strong></li><li><strong>No maquinas de lag</strong></li><li><strong>No multicuentas</strong></li><li><strong>No tener nick inapropiado o skin inapropiada</strong></li><li>El uso del <strong><code>/nick</code></strong> para hacerse pasar por usuarios/staff o que sean nombres ofensivos serán fuertemente sancionados.</li><li><strong>No robar cuentas de los jugadores</strong></li><li><strong>Venta de items en el servidor por algo externo a la network</strong></li><li><strong>Evadir sanciones</strong> solo te hará acreedor a una sanción más grande.</li><li>Cualquier archivo modificado o borrado recientemente: antes o durante la revisión es sancionable, esté en uso o no.</li><li><strong>Negarse a revisión</strong>, entrar después del tiempo establecido y/o desconectarse durante la advertencia o revisión es sancionable.</li><li><strong>Admitir el uso de hacks</strong> también es sancionable.</li><li>Queda estrictamente prohibida cualquier conducta que incentive el abandono temprano del servidor (killfarms de novatos, acoso, hostigamiento, matar a personas con kit inicial por diversión, etc) Justificada la kill si el kit inicial es el que está molestando/golpeando.</li><li>No se tiene permitido crear servidores externos de discord para la creación dichos eventos dentro de SilkCraft. Cualquier compartición incluye links en la comunidad o algún otro lado será eliminado o sancionado permanentemente de la red SilkCraft.</li><li><strong>No se permite romper la economía</strong> ninguna de las modalidades de la red de SilkCraft.</li><li><strong>No se permite vender rangos VIPS o items</strong> por algo externo de la network, ya sea dinero real etc.</li><li><strong>No se permite robar cuentas de Usuarios.</strong> (Existen responsabilidades de ello)</li><li><strong>No acuses a alguien sin pruebas</strong></li></ol><h2 id="chat" tabindex="-1">CHAT <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;CHAT&quot;">​</a></h2><ol><li><strong>No Spamming y disturbios</strong></li><li><strong>No toxicidad en el chat</strong></li><li><strong>No alterar el chat con discusiones</strong></li><li><strong>No toxicidad al staff</strong></li><li><strong>No toxicidad al equipo administrativo</strong></li><li>El acoso, discriminación y racismo no están permitidos.</li><li><strong>No compartir información de otros</strong></li><li><strong>No hacer publicidad ni promoción</strong></li><li><strong>No amenazar de muerte ni incitar al suicidio</strong></li><li><strong>No al mal uso de <code>/helpop</code> o <code>/report</code></strong></li><li><strong>No se permite fastidiar constantemente o acosar al staff</strong></li></ol><h2 id="multicuentas-y-uso-de-cuentas-afk" tabindex="-1">MULTICUENTAS Y USO DE CUENTAS AFK <a class="header-anchor" href="#multicuentas-y-uso-de-cuentas-afk" aria-label="Permalink to &quot;MULTICUENTAS Y USO DE CUENTAS AFK&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">ADVERTENCIA</p><p><strong>ESTA REGLA APLICA PARA TODAS LAS MODALIDADES</strong></p></div><h3 id="prohibido-el-uso-de-cuentas-secundarias-afk-o-activas" tabindex="-1">Prohibido el uso de cuentas secundarias (AFK o activas) <a class="header-anchor" href="#prohibido-el-uso-de-cuentas-secundarias-afk-o-activas" aria-label="Permalink to &quot;Prohibido el uso de cuentas secundarias (AFK o activas)&quot;">​</a></h3><p>Queda <strong>estrictamente prohibido</strong> el uso de cuentas adicionales, ya sea para dejar AFK, para automatizar tareas, o para obtener cualquier tipo de ventaja.</p><h3 id="¿que-se-considera-multicuenta" tabindex="-1">¿Qué se considera multicuenta? <a class="header-anchor" href="#¿que-se-considera-multicuenta" aria-label="Permalink to &quot;¿Qué se considera multicuenta?&quot;">​</a></h3><ol><li><strong>Cuentas AFK</strong>: Cuentas conectadas únicamente para mantener chunks cargados o beneficiar granjas, incluso si están inactivas.</li><li><strong>Cuentas secundarias</strong>: Cualquier cuenta adicional distinta a tu cuenta principal, sin importar si están activas o no.</li><li><strong>Islas separadas</strong>: En Skyblock, tener varias islas usando distintas cuentas también se considera multicuentas.</li></ol><h3 id="ejemplos-de-acciones-prohibidas" tabindex="-1">Ejemplos de acciones prohibidas <a class="header-anchor" href="#ejemplos-de-acciones-prohibidas" aria-label="Permalink to &quot;Ejemplos de acciones prohibidas&quot;">​</a></h3><ul><li>Dejar una cuenta secundaria en una granja (aunque esté solo parada).</li><li>Usar una cuenta para estar en el warp <code>/afk</code>.</li><li>Tener cuentas conectadas al mismo tiempo desde el mismo jugador.</li><li>Crear islas separadas con cuentas secundarias.</li><li>Usar cuentas para obtener recursos, kits, rangos, o beneficios duplicados.</li></ul><h3 id="sanciones" tabindex="-1">Sanciones <a class="header-anchor" href="#sanciones" aria-label="Permalink to &quot;Sanciones&quot;">​</a></h3><ul><li>Cualquier cuenta secundaria será <strong>baneada permanentemente</strong>.</li><li>La cuenta principal puede recibir <strong>sanciones graves</strong>, incluyendo baneo temporal o permanente según la gravedad y reincidencia.</li><li>Se revisarán IPs y conexiones compartidas regularmente.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Si encuentras algún jugador incumpliendo la normativa, por favor abre un ticket en nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a>.</p></div>',19)]))}const p=e(s,[["render",r]]);export{m as __pageData,p as default};
